from __future__ import absolute_import
from mock import Mock, MagicMock
from requests.structures import CaseInsensitiveDict
try:
    from pkg_resources import resource_filename
except ImportError:
    from importlib.resources import files
from six import u
import io


def response_from_file(module_name, path, status_code=200):
    """Returns a mock response for requests.get() with status code 200 and contents from given file."""
    try:
        resource_path = resource_filename(module_name, path)
    except ImportError:
        resource_path = files(module_name) / path
        resource_path = str(resource_path)
    content = _return_file_content(resource_path)
    return Mock(content=content, status_code=status_code, text=content)


def response_from_file_with_formatting(module_name, path, status_code=200, **kwargs):
    """Returns a mock response for requests.get() with status code 200 and contents from given file.
    Accepts named formatting of given file's content as keywords arguments."""
    try:
        resource_path = resource_filename(module_name, path)
    except ImportError:
        resource_path = files(module_name) / path
        resource_path = str(resource_path)
    content = _return_file_content(resource_path)
    content = _get_formatted_content(content, **kwargs)
    return Mock(content=content, status_code=status_code, text=content)


def _return_file_content(path):
    with io.open(path, 'r') as f:
            content = f.read()
    return content


def _get_formatted_content(content, **kwargs):
    return content.format(**kwargs)


def stream_response(*chunks, **kwargs):
    """Returns a mock response for requests.get() that acts as a stream response returning given chunks of data.
    Accepts status_code as a keyword argument (200 by default)."""
    status_code = kwargs.get('status_code', 200)
    stream_mock = MagicMock(status_code=status_code, iter_content=Mock(return_value=chunks))
    stream_mock.headers = CaseInsensitiveDict({'content-length': sum(len(u(chunk)) for chunk in chunks)})
    return stream_mock


def corrupted_stream_response(*chunks, **kwargs):
    """Returns a mock response for requests.get() that acts as a stream response returning given chunks of data.
    Accepts status_code as a keyword argument (200 by default)."""
    status_code = kwargs.get('status_code', 200)
    stream_mock = MagicMock(status_code=status_code, iter_content=Mock(return_value=chunks))
    stream_mock.headers = CaseInsensitiveDict({'content-length': sum(len(u(chunk)) for chunk in chunks) + 1})
    return stream_mock


def response(status_code=200, content=''):
    """Returns a mock response for requests.get() with given status code and empty content"""
    return Mock(content=content, status_code=status_code, text=content)
